    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

// Build the agent with tools
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Description = "An AI research agent that searches the web for information and takes notes to produce a final summary.",
    Instructions = """
        You are a research agent. When given a topic:
        1. Use the web_search tool to find relevant information (perform multiple searches with different queries).
        2. Use the save_note tool to record key findings as you go.
        3. Use the get_notes tool to review what you've collected.
        4. Once you have enough information, synthesize your notes into a clear, well-organized summary.
        Always cite sources where possible. Be thorough but concise.
        """,
    Tools = [AIFunctionFactory.Create(tools.WebSearch),
             AIFunctionFactory.Create(tools.SaveNote),
             AIFunctionFactory.Create(tools.GetNotes)],
};

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");

// --- Tools ---

public sealed class ResearchTools
{
    private static readonly HttpClient s_httpClient = new();
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a query. Returns relevant search results.")]
    public async Task<string> WebSearch(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  [Tool] Searching: \"{query}\"");

        try
        {
            // Uses DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var response = await s_httpClient.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            if (response.TryGetProperty("AbstractText", out var abstractText)
                && abstractText.GetString() is { Length: > 0 } text)
            {
                var source = response.TryGetProperty("AbstractSource", out var src) ? src.GetString() : "Unknown";
                var sourceUrl = response.TryGetProperty("AbstractURL", out var u) ? u.GetString() : "";
                results.Add($"Summary ({source}): {text}\nSource: {sourceUrl}");
            }

            if (response.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var t) && t.GetString() is { Length: > 0 } topicText)
                    {
                        var link = item.TryGetProperty("FirstURL", out var fu) ? fu.GetString() : "";
                        results.Add($"- {topicText} ({link})");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for \"{query}\". Try rephrasing the search.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note for later reference. Use this to record key findings.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} note(s)");
        return string.Join("\n---\n", _notes.Select((n, i) => $"[Note {i + 1}]: {n}"));
    }
}

