     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\nResearching: {topic}\n");

 // Use streaming to show output incrementally
 await foreach (var update in agent.RunStreamingAsync(
     $"Research the following topic and provide a comprehensive summary: {topic}"))
 {
     if (!string.IsNullOrEmpty(update.Text))
     {
         Console.Write(update.Text);
     }
 }

 Console.WriteLine("\n\n=== Research Complete ===");

 // --- Tools ---

 public sealed class ResearchTools
 {
     private static readonly HttpClient s_httpClient = new();
     private readonly List<string> _notes = [];

     [Description("Search the web for information on a query. Returns relevant search results.")]
     public async Task<string> WebSearch(
         [Description("The search query to look up")] string query)
     {
         Console.WriteLine($"  [Tool] Searching: \"{query}\"");

         try
         {
             // Uses DuckDuckGo Instant Answer API (no key required)
             var encoded = Uri.EscapeDataString(query);
             var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
             var response = await s_httpClient.GetFromJsonAsync<JsonElement>(url);

             var results = new List<string>();

             if (response.TryGetProperty("AbstractText", out var abstractText)
                 && abstractText.GetString() is { Length: > 0 } text)
             {
                 var source = response.TryGetProperty("AbstractSource", out var src)
                     ? src.GetString() : "Unknown";
                 var sourceUrl = response.TryGetProperty("AbstractURL", out var u)
                     ? u.GetString() : "";
                 results.Add($"Summary ({source}): {text}\nSource: {sourceUrl}");
             }

             if (response.TryGetProperty("RelatedTopics", out var topics)
                 && topics.ValueKind == JsonValueKind.Array)
             {
                 foreach (var item in topics.EnumerateArray().Take(5))
                 {
                     if (item.TryGetProperty("Text", out var t)
                         && t.GetString() is { Length: > 0 } topicText)
                     {
                         var link = item.TryGetProperty("FirstURL", out var fu)
                             ? fu.GetString() : "";
                         results.Add($"- {topicText} ({link})");
                     }
                 }
             }

             return results.Count > 0
                 ? string.Join("\n\n", results)
                 : $"No detailed results found for \"{query}\". Try rephrasing the search.";
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}. Try a different query.";
         }
     }

     [Description("Save a research note for later reference. Use this to record key findings.")]
     public string SaveNote(
         [Description("The note content to save")] string note)
     {
         _notes.Add(note);
         Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
         return $"Note saved. You now have {_notes.Count} note(s).";
     }

     [Description("Retrieve all saved research notes collected so far.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         Console.WriteLine($"  [Tool] Retrieving {_notes.Count} note(s)");
         return string.Join("\n---\n", _notes.Select((n, i) => $"[Note {i + 1}]: {n}"));
     }
 }
